  $s=$pdo->prepare("SELECT display_name_snapshot,username_snapshot,role_snapshot,course_code,attempt_number,score_percent,passed,correct_count,question_count,duration_seconds,completed_at FROM training_attempts WHERE organization_id=? AND status='completed' ORDER BY completed_at DESC,id DESC");$s->execute([$org]);
  header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="neptune-training-records.csv"');$out=fopen('php://output','w');fputcsv($out,['Name','Username','Role','Course','Attempt','Grade %','Passed','Correct','Questions','Duration seconds','Completed UTC']);foreach($s->fetchAll() as $r)fputcsv($out,[$r['display_name_snapshot'],$r['username_snapshot'],$r['role_snapshot'],$r['course_code'],$r['attempt_number'],$r['score_percent'],(int)$r['passed']===1?'Yes':'No',$r['correct_count'],$r['question_count'],$r['duration_seconds'],$r['completed_at']]);fclose($out);exit;
