$s=$pdo->prepare("SELECT u.id,u.display_name,u.username,u.role,u.active,
 (SELECT COUNT(*) FROM training_attempts a WHERE a.organization_id=u.organization_id AND a.user_id=u.id AND a.course_code='admin' AND a.status='completed') admin_attempts,
 (SELECT MAX(score_percent) FROM training_attempts a WHERE a.organization_id=u.organization_id AND a.user_id=u.id AND a.course_code='admin' AND a.status='completed') admin_best,
 (SELECT MAX(passed) FROM training_attempts a WHERE a.organization_id=u.organization_id AND a.user_id=u.id AND a.course_code='admin' AND a.status='completed') admin_passed,
 (SELECT COUNT(*) FROM training_attempts a WHERE a.organization_id=u.organization_id AND a.user_id=u.id AND a.course_code='scouter' AND a.status='completed') scout_attempts,
 (SELECT MAX(score_percent) FROM training_attempts a WHERE a.organization_id=u.organization_id AND a.user_id=u.id AND a.course_code='scouter' AND a.status='completed') scout_best,
 (SELECT MAX(passed) FROM training_attempts a WHERE a.organization_id=u.organization_id AND a.user_id=u.id AND a.course_code='scouter' AND a.status='completed') scout_passed,
 (SELECT MAX(completed_at) FROM training_attempts a WHERE a.organization_id=u.organization_id AND a.user_id=u.id AND a.status='completed') last_training
 FROM users u WHERE u.organization_id=? ORDER BY u.active DESC,u.display_name,u.username");$s->execute([$org]);$users=$s->fetchAll();
$s=$pdo->prepare("SELECT id,display_name_snapshot,username_snapshot,role_snapshot,course_code,attempt_number,score_percent,passed,correct_count,question_count,duration_seconds,completed_at FROM training_attempts WHERE organization_id=? AND status='completed' ORDER BY completed_at DESC,id DESC LIMIT 100");$s->execute([$org]);$attempts=$s->fetchAll();
